prompt --application/shared_components/user_interface/templates/region/stacked_sheets
begin
wwv_flow_imp_shared.create_plug_template(
 p_id=>wwv_flow_imp.id(978592452413208367)
,p_layout=>'TABLE'
,p_template=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<section class="amc-TStackedSheets #REGION_CSS_CLASSES#" id="#REGION_STATIC_ID#" #REGION_ATTRIBUTES# aria-labelledby="#REGION_STATIC_ID#_heading">',
'  <span class="amc-TStackedSheets-sheet amc-TStackedSheets-sheet--4" aria-hidden="true"></span>',
'  <span class="amc-TStackedSheets-sheet amc-TStackedSheets-sheet--3" aria-hidden="true"></span>',
'  <span class="amc-TStackedSheets-sheet amc-TStackedSheets-sheet--2" aria-hidden="true"></span>',
'  <span class="amc-TStackedSheets-sheet amc-TStackedSheets-sheet--1" aria-hidden="true"></span>',
'  <div class="amc-TStackedSheets-paper">',
'    <span class="amc-TStackedSheets-tape" aria-hidden="true"></span>',
'    <header class="amc-TStackedSheets-header">',
'      <span class="amc-TStackedSheets-sticker fa #ICON_CSS_CLASSES#" aria-hidden="true"></span>',
'      <h2 class="amc-TStackedSheets-title" id="#REGION_STATIC_ID#_heading">#TITLE#</h2>',
'      <div class="amc-TStackedSheets-actions">#HELP##EDIT##CHANGE##COPY##DELETE##CREATE#</div>',
'    </header>',
'    <div class="amc-TStackedSheets-body">#BODY##SUB_REGIONS#</div>',
'    <footer class="amc-TStackedSheets-footer">#PREVIOUS##CLOSE##NEXT#</footer>',
'  </div>',
'</section>'))
,p_page_plug_template_name=>'AMC Stacked Sheets'
,p_internal_name=>'AMC_TPL_STACKED_SHEETS'
,p_css_file_urls=>'#APP_FILES#amc-templates/amc-tpl-stacked-sheets.css'
,p_theme_id=>42
,p_default_label_alignment=>'RIGHT'
,p_default_field_alignment=>'LEFT'
,p_translate_this_template=>'N'
,p_template_comment=>'Region template that sets the region on a pile of paper sheets. The top sheet holds the native region content on the normal surface; the sheets behind are tinted from the palette and fan out on hover and when anything inside has keyboard focus. The region icon is shown as a small tilted sticker next to the title. Buttons in Help, Edit, Change, Copy, Delete and Create sit in the header, and Previous, Close and Next in the footer. Template options: Single sheet or Four sheets change the pile, Straight stack drops the tilt so sheets offset straight down, Strong tilt doubles it, Plain paper uses neutral sheets instead of palette tints, and No body padding. On wide regions the tilt is reduced automatically so the corners stay close to the region. Under reduced motion the pile does not move; in forced-colors mode the sheets become plain outlines.'
);
end;
